def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        base = 12.0 if hp > 3 else 28.0
        return float(min(budget, base))

    threats = []
    cindy_bid = None
    max_prev_bid = 0.0
    urgent_opp = False

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if prev and prev.get('bid') is not None:
            prev_bid = float(prev.get('bid', 0.0))
        if prev_bid > max_prev_bid:
            max_prev_bid = prev_bid
        if agent_id == 'Cindy':
            cindy_bid = prev_bid
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 2:
            urgent_opp = True
        threats.append((agent_id, prev_bid, opp.get('budget', 0.0), opp.get('hp', 10), opp.get('no_water_days', 0), opp.get('water_requirement', WATER_REQ)))

    competitors = len(alive) + 1
    expected_share = float(supply) / float(competitors * WATER_REQ)

    my_urgent = (hp <= 2) or (no_water >= 2)
    my_semi_urgent = (hp <= 4) or (no_water >= 1)

    if my_urgent:
        target = 62.0
        if cindy_bid is not None:
            target = max(target, min(92.0, cindy_bid + 2.0))
        if urgent_opp:
            target += 4.0
        return float(min(budget, target))

    if expected_share >= 0.45:
        base = 14.0
        if cindy_bid is not None and cindy_bid < 25.0:
            base = 18.0
        if my_semi_urgent:
            base += 8.0
        return float(min(budget, base))

    if expected_share >= 0.30:
        target = 24.0
        if cindy_bid is not None:
            if cindy_bid >= 70.0:
                target = 26.0
            elif cindy_bid >= 45.0:
                target = cindy_bid + 1.5
            else:
                target = 32.0
        if urgent_opp:
            target += 3.0
        if my_semi_urgent:
            target += 10.0
        return float(min(budget, target))

    target = 34.0
    if cindy_bid is not None:
        if cindy_bid >= 80.0:
            target = 30.0
        elif cindy_bid >= 55.0:
            target = cindy_bid + 1.5
        else:
            target = max(36.0, cindy_bid + 2.0)
    else:
        target = max(34.0, max_prev_bid + 1.0)

    if urgent_opp:
        target += 4.0
    if my_semi_urgent:
        target += 10.0
    if day >= 8 and hp > 4 and no_water == 0:
        target -= 4.0

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Identify alive opponents and read yesterday's bid only (immediate reaction)
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            prev = opp.get('previous_trace', {}) or {}
            if prev.get('bid') is not None:
                alive.append((opp_id, float(prev.get('bid', 0.0)), prev))

    # If no info, bid conservatively based on hp
    if not alive:
        if my_hp <= 2:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.55
        return float(min(my_budget, max(0.0, target)))

    # Use yesterday's highest bid as an estimate of Cindy-like aggressive pressure
    highest_prev_bid = max(b for _, b, _ in alive)

    # Supply pressure: when supply is higher, we can afford to contest slightly less
    # Normalize supply to [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, float(supply_norm)))

    # Base target: try to outbid the leader modestly, but cap to avoid budget starvation
    # If opponent bids were very high, we must respond more to secure enough water for survival.
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        if my_hp <= 2:
            target = DAILY_SALARY * (0.95 - 0.15 * supply_norm)
        else:
            target = min(highest_prev_bid + 2.0, DAILY_SALARY * (0.70 - 0.05 * supply_norm) + 0.25 * highest_prev_bid)
    else:
        # Mid/low pressure: bid enough to stay competitive against a potential swing.
        if my_hp <= 2:
            target = DAILY_SALARY * (0.70 - 0.10 * supply_norm)
        else:
            # Slightly above what mid bidders likely use
            target = max(DAILY_SALARY * 0.45, highest_prev_bid + 1.5)
            target = min(target, DAILY_SALARY * (0.65 - 0.05 * supply_norm) + 0.2 * highest_prev_bid)

    # Ensure we don't overpay when budget is tight
    # Also ensure at least some bid unless budget is extremely low
    if my_budget <= 0.0:
        return 0.0

    # If my budget is low relative to target, scale down but keep competitiveness when hp is critical
    if target > my_budget:
        if my_hp <= 2:
            target = my_budget * 0.95
        else:
            target = my_budget * 0.65

    # Final clamp
    target = float(max(0.0, target))
    return float(min(my_budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    desperate_for_water = my_status['no_water_days'] >= 2
    urgent_need_for_water = my_status['no_water_days'] == 1

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    remaining_days = EPISODE_DAYS - day_context['day'] + 1

    if desperate_for_water:
        return min(my_status['budget'], DAILY_SALARY * 0.99)
    elif urgent_need_for_water:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid + 5.0))
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.8)
    else:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                if remaining_days > 0 and my_status['budget'] / remaining_days < DAILY_SALARY * 0.7:
                    return min(my_status['budget'], DAILY_SALARY * 0.75)
                else:
                    return min(my_status['budget'], DAILY_SALARY * 0.4)
            else:
                return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 2.0))
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.6)

def get_bid(day_context, my_status, opponents_status):
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    yesterday_max_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_max_bid = max(yesterday_max_bid, prev['bid'])

    if hp <= 2:
        target = DAILY_SALARY * 0.95
    elif hp <= 5:
        target = max(DAILY_SALARY * 0.6, yesterday_max_bid + 2)
    else:
        target = max(1, yesterday_max_bid * 0.75 - 5)

    bid = min(budget, max(0, target))
    return bid
